import React, { ComponentType, ReactNode } from 'react';
import * as ReactDOM from 'react-dom';
import { ErrorBoundary } from 'react-error-boundary';

import { HighlighterProvider } from '@teambit/react.ui.highlighter-provider';
import { type ReactLiveComposition, needLiveControls, LivePreview } from '@bitdev/react.live-controls';
import { getDefaultControlsHook } from '@teambit/react.ui.mounter.use-default-controls';
import { getLiveControls } from '@teambit/react.modules.react-live-controls-from-schema';

// Prepare <AutoLiveControlsPreview /> to wrap <LivePreview />
// with auto controls feature.

const useDefaultControls = getDefaultControlsHook(getLiveControls);

function AutoLiveControlsPreview(props: ReactLiveComposition) {
  const resultProps = { ...props };
  const enabled = !resultProps.controls && !resultProps.noControls;
  const defaultControls = useDefaultControls(enabled);
  if (enabled && defaultControls.length) {
    resultProps.controls = defaultControls;
  }
  return (
    <LivePreview {...resultProps} />
  );
}

// TODO: remove when stable.
function activateLiveControls() {
  if (window.parent) {
    window.parent.postMessage({
      type: 'composition-live-controls:activate',
    }, '*');
  }
}
activateLiveControls();

/**
 * a reference to a provider function.
 */
export type MounterProvider = ComponentType<{ children: ReactNode }>;

type Root = { render: (element: React.ReactElement) => void; unmount: () => void };

// react-dom's export surface varies by major version. Read exports by computed
// key so bundlers' ESM linkers don't warn about exports that are absent in the
// installed version (createRoot is absent on 17, render is absent on 19).
const reactDomExport = (name: string) => (ReactDOM as Record<string, any>)[name];

/**
 * resolve a createRoot-style root factory for whichever react-dom (17/18/19+)
 * is installed, using only module requests that resolve in ALL of them.
 *
 * react-dom/client must not be referenced here at all: it does not resolve on
 * React 17, so any reference in the module graph fails React 17 builds, and
 * hiding the request from the bundler (webpackIgnore) emits a browser-native
 * bare-specifier import that can never resolve without an import map — which
 * silently sent every browser down the legacy fallback and broke React 19,
 * where the legacy ReactDOM.render API was removed.
 */
async function resolveRootFactory(): Promise<(container: HTMLElement) => Root> {
  // React 18: the root entry exports createRoot. Call it the way react-dom/client
  // does — toggling usingClientEntryPoint — so development builds don't warn
  // about the import site.
  const createRoot = reactDomExport('createRoot');
  if (typeof createRoot === 'function') {
    const internals = reactDomExport('__SECRET_INTERNALS_DO_NOT_USE_OR_YOU_WILL_BE_FIRED');
    return (container) => {
      if (internals) internals.usingClientEntryPoint = true;
      try {
        return createRoot(container);
      } finally {
        if (internals) internals.usingClientEntryPoint = false;
      }
    };
  }

  // React 17: no createRoot anywhere — wrap the legacy API.
  const legacyRender = reactDomExport('render');
  if (typeof legacyRender === 'function') {
    return (container): Root => ({
      render: (element) => legacyRender(element, container),
      unmount: () => reactDomExport('unmountComponentAtNode')(container),
    });
  }

  // React 19+: createRoot moved off the root entry. react-dom/profiling is the
  // one entry that resolves on 17, 18 and 19 alike and exposes the same
  // createRoot as react-dom/client on 18/19 (in development it is the exact
  // module react-dom itself loads). It is only ever loaded on this branch.
  // @ts-ignore react-dom ships no type declarations for the profiling entry.
  const profiling: any = await import('react-dom/profiling');
  return (container) => profiling.createRoot(container);
}

const rootFactory = resolveRootFactory();

/**
 * a reference to a root instance.
 */
let root: Root | null = null;
/**
 * a reference to the root document.
 */
let rootDoc: HTMLElement | null = null;

/**
 * create a mounter.
 */
export function createMounter(Provider: MounterProvider = React.Fragment): any {
  return async (Composition: React.ComponentType | ReactLiveComposition) => {
    const isLiveComposition = typeof Composition === 'object';

    if (isLiveComposition && !needLiveControls(window.location)) {
      // eslint-disable-next-line no-param-reassign
      Composition.noControls = true;
    }

    if (root && rootDoc) {
      // Unmount the existing root before mounting a new one.
      root.unmount();
      root = null;
      rootDoc = null;
    }

    const createCompatRoot = await rootFactory;
    rootDoc = document.getElementById('root');
    root = createCompatRoot(rootDoc!);

    root.render(
      // @ts-ignore TODO: remove this after release.
      <ErrorBoundary fallback={<></>}>
        {/* @ts-ignore TODO: need a react18 HighlighterProvider to fix this */}
        <HighlighterProvider>
          <Provider>
            {isLiveComposition ? (
              <AutoLiveControlsPreview {...Composition} />
            ) : (
              <Composition />
            )}
          </Provider>
        </HighlighterProvider>
      </ErrorBoundary>
    );
  };
}

export default createMounter;
